begin;
create table dcc_private.progression_catalog(singleton boolean primary key default true check(singleton), data jsonb not null);
revoke all on dcc_private.progression_catalog from public,anon,authenticated;
-- BEGIN PROGRESSION DATA
insert into dcc_private.progression_catalog values(true,$catalog${"version":"core-081226-v1","source":"carl_rpg_core_rulebook_digital_hi-res_081226.pdf","options":[{"id":"amazonian","name":"Amazonian","page":129,"kind":"race","earth":true,"earthOnly":false,"size":4,"stats":{"strength":6,"intelligence":0,"constitution":0,"dexterity":3,"charisma":0},"skills":{"bow":2,"endurance":2,"pugilism":2},"dr":2,"defenses":{},"choices":[],"requirements":[{"kind":"physicalSkill","rank":5}],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Medium (4)\n• +6 Strength\n• +3 Dexterity\n• +2 Bow, Endurance, and Pugilism Skills\n• +2 DR\n• Each floor, you receive a coupon good for one free training at a Weapon Training Guild","source":"core-081226","version":1},{"id":"arachnid","name":"Arachnid","page":129,"kind":"race","earth":true,"earthOnly":false,"size":4,"stats":{"strength":0,"intelligence":0,"constitution":0,"dexterity":5,"charisma":0},"skills":{"web":3,"climbing":2,"perception":2,"performance":2},"dr":0,"defenses":{},"choices":[],"requirements":[],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Medium (4)\n• +5 Dexterity\n• +3 Web Spell, which costs half the normal Mana to cast\n• +2 Climbing, Perception, and Performance (with a stringed instrument specialty) Skills\n• You have an innate Climb Move equal to your normal Move value, without needing Checks (unless under duress)","source":"core-081226","version":1},{"id":"cat","name":"Cat","page":130,"kind":"race","earth":true,"earthOnly":false,"size":2,"stats":{"strength":-3,"intelligence":0,"constitution":2,"dexterity":4,"charisma":1},"skills":{"cat-like-reflexes":3,"slice-attack":2},"dr":0,"defenses":{},"choices":[],"requirements":[{"kind":"fact","key":"originalSpecies","value":"cat"}],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Small (2); Animal\n• +4 Dexterity\n• +2 Constitution\n• +1 Charisma\n• −3 Strength\n• +3 Cat-like Reflexes\n• +2 Slice Attack Skill\n• Can see in total darkness\n• Advantage on Cat-like Reflexes Skill Checks\n• Nine Lives: Take half damage from the first 9 attacks each day\n• Vulnerability: Take double damage from Dogs and Beasts","source":"core-081226","version":1},{"id":"cat-girl-cat-boy","name":"Cat Girl/Cat Boy","page":130,"kind":"race","earth":true,"earthOnly":false,"size":4,"stats":{"strength":0,"intelligence":0,"constitution":-2,"dexterity":3,"charisma":3},"skills":{"cat-like-reflexes":2,"good-first-impression":2,"light-on-your-feet":2,"slice-attack":2},"dr":0,"defenses":{},"choices":[],"requirements":[],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Medium (4)\n• +3 Dexterity and Charisma\n• −2 Constitution\n• +2 Cat-like Reflexes, Good First Impression, Light on your Feet, and Slice Attack Skills\n• Your Slice Attacks may add your Cha Mod to the damage instead of Str\n• Toxoplasma G.: Once per day, your allies have Rank 5 Catcher Skill (and the +5 DR Upgrade!) for one round to protect only you from attacks about to hit you. Those who do gain 1 AI Favor\n• When dealing with felines other than Cat Girls/ Boys, you make Charisma-based Skill Checks with Disadvantage","source":"core-081226","version":1},{"id":"changbi-demon","name":"Changbi Demon","page":130,"kind":"race","earth":true,"earthOnly":false,"size":4,"stats":{"strength":3,"intelligence":0,"constitution":3,"dexterity":5,"charisma":-2},"skills":{"ambush":3,"club":3},"dr":0,"defenses":{"Holy":{"resistant":false,"vulnerable":true,"immune":false}},"choices":[],"requirements":[{"kind":"fact","key":"deity","value":false}],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Medium (4)\n• +5 Dexterity\n• +3 Strength and Constitution\n• −2 Charisma\n• +3 Ambush and Creepy Chains (Club) Skills\n• Creepy Chains: Can use any chain as a weapon (use the Club Weapon Skill, but with a 10ft range). A Changbi Demon can lengthen or shorten any chain by 50% once per scene\n• Each time a foe touches a Changbi Demon with their bare skin (such as with Hand-to-Hand attacks), that foe takes 1d4+F Acid\n• No need to breathe\n• Vulnerable to Holy damage\n• Cannot worship a deity","source":"core-081226","version":1},{"id":"changeling","name":"Changeling","page":130,"kind":"race","earth":true,"earthOnly":false,"size":5,"stats":{"strength":0,"intelligence":2,"constitution":0,"dexterity":0,"charisma":3},"skills":{"ambush":2,"deception":2,"escape-artist":1},"dr":0,"defenses":{},"choices":[],"requirements":[],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Large (5)\n• +3 Charisma\n• +2 Intelligence\n• +2 Ambush and Deception Skills\n• +1 Escape Artist Skill\n• Advantage on Deception Skill Checks when no talking is needed\n• Changelings gain free access to organizations and producers by impersonating other crawlers and Syndicate celebrities, but can only use those relevant to the currently shifted individual\n• Changeling Shapeshifting: A Changeling who touches a member of another Race can shapeshift themselves into that Race, building a “library” of Races they can transform into. A Changeling can shapeshift into another Race as an Action to make an Unopposed Deception Skill Check. While shapeshifted into that other Race, they gain that Race’s bonuses other than statistics and Skills. For example, a Changeling shapeshifted into a Crocodilian would gain the Race’s Advantage on Intimidation Skill Checks, DR Buff, bonus after a full meal, and additional fatigue penalty on Charisma-based Checks\n• While shapeshifted into another Race, these changes are conveyed to World Dungeon systems, including information on viewers’ HUDs, mini-maps, and other systems\n• Changelings can’t touch mimics- type creatures. Don’t ask why or what happens—it’s bad","source":"core-081226","version":1},{"id":"crocodilian","name":"Crocodilian","page":131,"kind":"race","earth":true,"earthOnly":false,"size":5,"stats":{"strength":4,"intelligence":0,"constitution":3,"dexterity":0,"charisma":0},"skills":{"pugilism":2,"powerful-strike":2},"dr":3,"defenses":{},"choices":[],"requirements":[],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Large (5)\n• +4 Strength\n• +3 Constitution\n• +2 Pugilism and Powerful Strike Skills\n• When physically menacing someone in person, roll Intimidate Skill Checks with Advantage\n• +3 DR Buff\n• +1 Buff for all of your Skill Checks for 1 hour after eating a full meal\n• While you have the Fatigued Debuff, roll all Charisma-based Checks with Disadvantage","source":"core-081226","version":1},{"id":"doppelganger","name":"Doppelgänger","page":131,"kind":"race","earth":true,"earthOnly":false,"size":4,"stats":{"strength":3,"intelligence":0,"constitution":4,"dexterity":0,"charisma":0},"skills":{"deception":1,"endurance":1},"dr":2,"defenses":{},"choices":[],"requirements":[{"kind":"fact","key":"originalSize","value":true}],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Unchanged, but size changes when shifting\n• +4 Constitution\n• +3 Strength\n• +1 Deception and Endurance Skills\n• +2 DR\n• Due to shifting mass, can determine their maximum weight to lift based on Constitution instead of Strength\n• Advantage on Escape Artist Skill Checks and can make such Checks while being Held or watched\n• Once per scene, as an Action, you can incorporate a held weapon into their mass to deal additional damage equal to their Con Mod. Items incorporated this way can’t be disarmed\n• Doppelgänger Shape-Changing: As an Action, you can transform into any shape of comparable mass, incorporating carried and worn items into the new shape in the same percentage (that is, a Doppelgänger holding metal equal to half their weight must assume a shape that is one-third metal). This transformation is painful, causing you to mark off 1 Health Bar slot per change. If you attempt to change your shape to resemble a specific person or object, do so with an Unopposed Deception Skill Check","source":"core-081226","version":1},{"id":"dwarf-classic","name":"Dwarf, Classic","page":132,"kind":"race","earth":true,"earthOnly":false,"size":4,"stats":{"strength":0,"intelligence":2,"constitution":4,"dexterity":0,"charisma":-2},"skills":{"endurance":2},"dr":0,"defenses":{},"choices":[{"id":"craft","label":"Two crafting Skills","ids":["alchemy","arcane","calligraphy","cooking","engineering","fabricate","infusion","repair","smithing","tattoo-artistry"],"bonus":3,"count":2}],"requirements":[],"rank20":[],"rank20Groups":["crafting"],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Medium (4)\n• +4 Constitution\n• +2 Intelligence\n• −2 Charisma\n• +3 in two different crafting Skills of your choice\n• +2 Endurance Skill\n• Can see in total darkness\n• All crafting Skills can be raised to Rank 20\n• When dealing with elves or fairies, make all Charisma-based Checks with Disadvantage","source":"core-081226","version":1},{"id":"dwarf-fathom","name":"Dwarf, Fathom","page":132,"kind":"race","earth":true,"earthOnly":false,"size":4,"stats":{"strength":2,"intelligence":0,"constitution":3,"dexterity":0,"charisma":0},"skills":{"engineering":3,"dumpster-diving":2,"salvage":2},"dr":0,"defenses":{},"choices":[],"requirements":[],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Medium (4)\n• +3 Constitution\n• +2 Strength\n• +3 Engineering Skill\n• +2 Dumpster Diving and Salvage Skills\n• Roll d20 Checks with Advantage when earth, rocks, and dirt are involved\n• Can produce a 15ft Cone of light from a harmless lizard nesting atop their heads, and can easily acquire a new lizard if the existing one is lost or killed","source":"core-081226","version":1},{"id":"elf-high","name":"Elf, High","page":133,"kind":"race","earth":true,"earthOnly":false,"size":4,"stats":{"strength":0,"intelligence":4,"constitution":0,"dexterity":4,"charisma":4},"skills":{"intimidate":2,"lore":1},"dr":0,"defenses":{},"choices":[{"id":"rank20","label":"Skills permitted to reach Rank 20","ids":["animal-handling","deception","diplomacy","good-first-impression","leadership","negotiation","performance","persuasion","streetwise","taunt","earworm","holy-aura","mind-tickle","paladins-smite","panty-dropper"],"bonus":0,"count":2,"cap20":true}],"requirements":[],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Medium (4)\n• +4 Intelligence, Dexterity, and Charisma\n• +2 Intimidation Skill, and you can use your Cha Mod\n• +1 Lore Skill\n• You recover Mana at twice the normal rate in a natural environment\n• Add 1d4 to your Evade Checks\n• When dealing with Dwarves, Rat-Kin, or anyone smelly or dirty, make all Charisma-based Checks with Disadvantage\n• Two different Charisma-based Skills can be raised to Rank 20","source":"core-081226","version":1},{"id":"elf-city","name":"Elf, City","page":133,"kind":"race","earth":true,"earthOnly":false,"size":4,"stats":{"strength":0,"intelligence":0,"constitution":0,"dexterity":0,"charisma":0},"skills":{"good-first-impression":3,"negotiation":2,"streetwise":2},"dr":0,"defenses":{},"choices":[],"requirements":[],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":{"total":6,"keys":["intelligence","dexterity","charisma"]},"notes":"• Size: Medium (4)\n• +6 to split as you please between Intelligence, Dexterity, and Charisma\n• +3 Good First Impression Skill\n• +2 Negotiation and Streetwise Skills\n• Once per floor during a Long Rest, a City Elf can adjust the +4 spent between Charisma, Intelligence, and Dexterity, reassigning those points between those Stats\n• When entering a settlement for the first time, make your first Charisma-based Check with Advantage. On an Amazing Success or better, you have made a permanent contact\nPublication note: initial split is +6, but the later reassignment sentence says +4. Reassignment requires a GM ruling; it is not automated.","source":"core-081226","version":1},{"id":"elf-night","name":"Elf, Night","page":134,"kind":"race","earth":true,"earthOnly":false,"size":4,"stats":{"strength":0,"intelligence":3,"constitution":0,"dexterity":3,"charisma":0},"skills":{"acute-ears":3,"hide-in-shadows":3},"dr":0,"defenses":{},"choices":[{"id":"rank20","label":"Skills permitted to reach Rank 20","ids":["alchemy","arcane","calligraphy","cooking","engineering","fabricate","infusion","repair","smithing","tattoo-artistry"],"bonus":0,"count":1,"cap20":true}],"requirements":[],"rank20":["hide-in-shadows"],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Medium (4)\n• +3 Intelligence and Dexterity\n• +3 Acute Ears and Hide in Shadows Skills\n• Can see total darkness\n• Gain Advantage when you use the Hide in Shadows Skill at night\n• Once per day, can instruct the shadow of a living thing to use the Taunt Skill at Rank equal to Floor Number (and no Stat Mod) to pull attacks away from you\n• Hide in Shadows and one crafting Skill of your choice can be raised to Rank 20","source":"core-081226","version":1},{"id":"frost-maiden","name":"Frost Maiden","page":134,"kind":"race","earth":true,"earthOnly":false,"size":3,"stats":{"strength":0,"intelligence":2,"constitution":0,"dexterity":2,"charisma":2},"skills":{"persuasion":2},"dr":0,"defenses":{},"choices":[],"requirements":[],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Petite (3)\n• +2 Charisma, Intelligence, and Dexterity\n• +2 Persuasion Skill\n• Melee attacks deal +1d4 Ice damage\n• Roll with Advantage on Int and Con Stat Checks\n• The crawler’s Game Guide becomes their Manager\n• Capable of flight for up to 1 minute per scene","source":"core-081226","version":1},{"id":"human","name":"Human","page":135,"kind":"race","earth":true,"earthOnly":false,"size":4,"stats":{"strength":2,"intelligence":2,"constitution":2,"dexterity":2,"charisma":2},"skills":{},"dr":0,"defenses":{},"choices":[],"requirements":[],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Typically Medium (4)\n• +2 to all Stats\n• At the end of each floor, roll one Skill Advancement Check with Advantage if that Skill is Rank 9 or less\n• Gain 1 AI Favor each time you level up\n• When you take damage, you may spend 1 AI Favor to gain DR equal to your Con (as many times as you have AI Favor to spend)\n• Once per day, when you would make an untrained Skill Check on a non-Passive Utility Skill, you can roll as if you had 2 Ranks in the Skill\n• Once per floor, you can spend an Action to remove any single Debuff you’re suffering from, even Injuries","source":"core-081226","version":1},{"id":"igneous","name":"Igneous","page":135,"kind":"race","earth":true,"earthOnly":false,"size":5,"stats":{"strength":4,"intelligence":-2,"constitution":6,"dexterity":0,"charisma":-2},"skills":{"endurance":1},"dr":3,"defenses":{"Fire":{"resistant":false,"vulnerable":false,"immune":true},"Ice":{"resistant":false,"vulnerable":true,"immune":false}},"choices":[],"requirements":[],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Large (5)\n• +6 Constitution\n• +4 Strength\n• −2 Intelligence and Charisma\n• +1 Endurance Skill\n• +3 DR Buff\n• Once per day, double your Move for 20 seconds\n• As an Action, make a Con Stat Check. On Success, deal 1d8+F Fire damage, 5ft Burst radius\n• No Survival Checks needed in harsh heat conditions and can breathe underwater\n• Immunity to Fire damage, and vulnerable to Ice damage\n• Ability to burrow\n• Lose 1 Health Bar slot each time you access your Inventory (not Hotlist)\n• Disadvantage on Checks to conceal your presence or nature (such as Stealth)","source":"core-081226","version":1},{"id":"lajabless","name":"Lajabless","page":136,"kind":"race","earth":true,"earthOnly":false,"size":4,"stats":{"strength":0,"intelligence":0,"constitution":0,"dexterity":0,"charisma":0},"skills":{},"dr":0,"defenses":{},"choices":[{"id":"weapon","label":"Weapon Skill","ids":["axe","dagger","longsword","rapier","club","improvised-weapons","warhammer","lance","polearm","quarterstaff","bow","crossbow","handgun","shotgun","javelin","shuriken","slingshot","herding-weapons"],"bonus":3,"count":1},{"id":"spell","label":"Spell choice","ids":["air-buddy","astral-paw","bad-faith","bang-bro","clockwork-triplicate","confusing-fog","dirt-clod","drain-life","earworm","fear","fireball","fire-fingers","frost-scar","grand-illusion","heal-critter","heal-others","heal-self","hole","holy-aura","hot-stuff-aura","ice-blast","icicles","intimate-touches","lightning-bolt","magic-missile","mind-tickle","minion-army","natures-breath","oakhide","paladins-smite","panty-dropper","ping","puddle-jumper","rise-dead-minion","rootfoot","second-chance","shield","shock-treatment","solsplash","soul-collector","thunderlash","torch","turn-undead","twinkle-toes","unnecessary-force","vine-porn","wall-of-fire","water-breathing","web","wilburs-slow-build-fireblast","wisp-armor"],"bonus":2,"count":2}],"requirements":[],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Medium (4)\n• +5 Intelligence during the day, +5 Strength during the night\n• +2 in two Spells of your choice\n• +3 in one Weapon Skill of your choice\n• Advantage when using the Ambush and Intimidation Skill\n• During the day, Strength is halved, but Spells cost half the Mana to cast\n• During the night, Strength is doubled, but Spells cost double the Mana to cast","source":"core-081226","version":1},{"id":"obsidian-butterfly","name":"Obsidian Butterfly","page":136,"kind":"race","earth":true,"earthOnly":false,"size":4,"stats":{"strength":0,"intelligence":2,"constitution":-4,"dexterity":3,"charisma":0},"skills":{"intimidate":2,"slice-attack":2},"dr":0,"defenses":{},"choices":[{"id":"spell","label":"Spell choice","ids":["air-buddy","astral-paw","bad-faith","bang-bro","clockwork-triplicate","confusing-fog","dirt-clod","drain-life","earworm","fear","fireball","fire-fingers","frost-scar","grand-illusion","heal-critter","heal-others","heal-self","hole","holy-aura","hot-stuff-aura","ice-blast","icicles","intimate-touches","lightning-bolt","magic-missile","mind-tickle","minion-army","natures-breath","oakhide","paladins-smite","panty-dropper","ping","puddle-jumper","rise-dead-minion","rootfoot","second-chance","shield","shock-treatment","solsplash","soul-collector","thunderlash","torch","turn-undead","twinkle-toes","unnecessary-force","vine-porn","wall-of-fire","water-breathing","web","wilburs-slow-build-fireblast","wisp-armor"],"bonus":2,"count":1}],"requirements":[{"kind":"groupSkill","group":"edged","rank":5}],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Medium (4), mostly due to wings\n• +3 Dexterity\n• +2 Intelligence\n• −4 Constitution\n• +2 Intimidate and Slice Attack Skills\n• +2 in a Spell of your choice\n• Has four translucent butterfly wings that can reach up to 15 feet and deliver touch- or melee-range Spells\n• May use Cha Mod instead of Con Mod in their Health Bar\n• Upon entering the Sixth Floor, choose to either gain Stronger Wings (wings are now capable of flight for up to 2 minutes per scene, with +20ft Move when flying) or Ferocious Visage (Advantage when using any Skill to inspire fear or respect)\n• Add 1d4 to your Evade Checks","source":"core-081226","version":1},{"id":"primal","name":"Primal","page":137,"kind":"race","earth":true,"earthOnly":false,"size":4,"stats":{"strength":-1,"intelligence":-1,"constitution":-1,"dexterity":-1,"charisma":-1},"skills":{},"dr":0,"defenses":{},"choices":[],"requirements":[{"kind":"fact","key":"originalRace","value":true},{"kind":"fact","key":"originalSize","value":true}],"rank20":[],"rank20Groups":["all"],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Unchanged\n• −1 to all Stats\n• All Skills can be raised to Rank 20\nSelect the original Race in benefit choices; its package is included once before the Primal modifiers.","source":"core-081226","version":1},{"id":"rat-hooligan","name":"Rat Hooligan","page":137,"kind":"race","earth":true,"earthOnly":false,"size":3,"stats":{"strength":0,"intelligence":0,"constitution":1,"dexterity":2,"charisma":0},"skills":{"escape-plan":2,"stealth":2,"bite":1,"survival":1},"dr":0,"defenses":{},"choices":[],"requirements":[],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Petite (3)\n• +2 Dexterity\n• +1 Constitution\n• +2 Escape Plan and Stealth Skills\n• +1 Bite and Survival Skills\n• Advantage on Checks to resist hunger and thirst\n• Can converse with common house rats to gather minimal information while in buildings\n• May add Dex Mod to Bite damage instead of Str","source":"core-081226","version":1},{"id":"sasquatch","name":"Sasquatch","page":137,"kind":"race","earth":true,"earthOnly":false,"size":5,"stats":{"strength":6,"intelligence":-3,"constitution":6,"dexterity":2,"charisma":-1},"skills":{"foot-soldier":3,"smush":3},"dr":0,"defenses":{},"choices":[],"requirements":[{"kind":"skill","id":"smush","rank":5}],"rank20":["smush"],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Large (5)\n• +6 Strength and Constitution\n• +2 Dexterity\n• −3 Intelligence\n• −1 Charisma\n• +3 Foot Soldier and Smush Skills\n• Smush Skill can be raised to Rank 20","source":"core-081226","version":1},{"id":"tetrakai","name":"Tetrakai","page":138,"kind":"race","earth":true,"earthOnly":false,"size":4,"stats":{"strength":0,"intelligence":0,"constitution":0,"dexterity":6,"charisma":-2},"skills":{"pugilism":2,"wrasslin":2,"axe":1,"dagger":1,"longsword":1,"rapier":1},"dr":0,"defenses":{},"choices":[],"requirements":[],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Medium (4)\n• +6 Dexterity\n• −2 Charisma\n• +2 Pugilism and Wrasslin’ Skills\n• +1 in all Edged Weapon Skills\n• Four Arms: Your Hands/Holding Gear slot allows for four items (or two weapons requiring two hands)","source":"core-081226","version":1},{"id":"tigran","name":"Tigran","page":138,"kind":"race","earth":true,"earthOnly":false,"size":4,"stats":{"strength":2,"intelligence":0,"constitution":0,"dexterity":3,"charisma":-4},"skills":{"ambush":2,"cat-like-reflexes":2,"slice-attack":2},"dr":1,"defenses":{},"choices":[],"requirements":[],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Medium (4)\n• +3 Dexterity\n• +2 Strength\n• −4 Charisma\n• +2 Ambush, Cat-like Reflexes, and Slice Attack Skills\n• Can see in total darkness\n• +1 DR Buff\n• +10ft Move\n• When attacking during a Surprise Action, deal ×2 total damage with melee attacks\n• Disadvantage on Dexterity-based Skills that require fine manipulation or motor coordination","source":"core-081226","version":1},{"id":"bune","name":"Bune","page":139,"kind":"race","earth":false,"earthOnly":false,"size":4,"stats":{"strength":0,"intelligence":3,"constitution":-2,"dexterity":2,"charisma":0},"skills":{"determine-value":3,"fabricate":3,"negotiation":3},"dr":0,"defenses":{},"choices":[],"requirements":[{"kind":"popularity","minimum":3}],"rank20":[],"rank20Groups":[],"statCaps":{},"skillPenalties":{},"splitStats":null,"notes":"• Size: Medium (4)\n• +3 Intelligence\n• +2 Dexterity\n• −2 Constitution\n• +3 Determine Value, Fabricate, and Negotiation Skills\n• At Level 50, +2 Dexterity and gain wings capable of flying up to 500ft per scene\n• +1 Popularity each time you roll a Critical Hit in combat","source":"core-081226","version":1},{"id":"caprid","name":"Caprid","page":139,"kind":"race","earth":false,"earthOnly":false,"size":5,"stats":{"strength":-2,"intelligence":3,"constitution":0,"dexterity":0,"ch