-- END PROGRESSION DATA
alter table public.dcc_crawlers add column progression jsonb not null default '{"version":1,"evidence":{"facts":{},"popularity":null,"identityLimits":false},"definitions":[],"offers":[],"rewardDecision":null,"selection":null}';
-- Do not update any 015/018 balances, flags, grants, resources or versions here.

create function dcc_private.progression_data() returns jsonb language sql stable security definer set search_path='' as $$select data from dcc_private.progression_catalog$$;
create function dcc_private.progression_item(kind text,ident text) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
 select value into result from jsonb_array_elements(dcc_private.progression_data()->kind) where value->>'id'=ident;
 if result is null then raise exception 'Unknown reviewed progression definition.' using errcode='22023';end if;return result;
end $$;
-- Expand identity lookup while retaining the exact original 018 mechanics for old saves.
update dcc_private.selection_catalog set data=jsonb_build_object(
 'races',(select jsonb_agg(value||jsonb_build_object('requirement','none')) from jsonb_array_elements(dcc_private.progression_data()->'options') where value->>'kind'='race'),
 'classes',(select jsonb_agg(value||jsonb_build_object('requirement','none')) from jsonb_array_elements(dcc_private.progression_data()->'options') where value->>'kind'='class'),
 'abilities',dcc_private.progression_data()->'abilities');
-- Keep 018's pre-grant prerequisite tags and all reviewed starter definitions intact.
-- The original migration's catalog is a frozen snapshot, restored below by the synchronizer's test comparison.
update dcc_private.selection_catalog set data=jsonb_set(jsonb_set(data,'{races}',
 (select jsonb_agg(case when value->>'id'='amazonian' then value||'{"requirement":"physical-skill-5"}'::jsonb else value end) from jsonb_array_elements(data->'races'))),'{classes}',
 (select jsonb_agg(case when value->>'id'='monster-truck-driver' then value||'{"requirement":"driving-5"}'::jsonb else value end) from jsonb_array_elements(data->'classes')));

create function dcc_private.progression_custom(b jsonb,bases jsonb,skills jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare t jsonb;l jsonb;a jsonb;v jsonb;prior jsonb;result jsonb;issues jsonb:='[]';stats jsonb:='{"strength":0,"intelligence":0,"constitution":0,"dexterity":0,"charisma":0}';grants jsonb:='{}';defenses jsonb:='{}';caps jsonb:='{}';penalties jsonb:='{}';penalty_counts jsonb:='{}';rank20 jsonb:='[]';rankgroups jsonb:='[]';seen text[]:=array[]::text[];target text;effect text;k text;notes text:=coalesce(b->>'description','');quantity integer;cost integer;spent integer:=0;refund integer:=0;statpen integer:=0;skillpen integer:=0;passives integer:=0;dr integer:=0;move integer:=20;step integer:=10;size integer:=4;n integer;ids jsonb;sk jsonb;
begin
 if jsonb_typeof(b)<>'object' or b->>'kind' is null or b->>'kind' not in ('race','class') or jsonb_typeof(b->'name') is distinct from 'string' or length(btrim(b->>'name')) not between 1 and 100 or jsonb_typeof(b->'description') is distinct from 'string' or length(b->>'description')>2000 or jsonb_typeof(b->'earth') is distinct from 'boolean' or jsonb_typeof(b->'lines') is distinct from 'array' then raise exception 'Invalid custom build.' using errcode='22023';end if;
 if jsonb_array_length(b->'lines')>60 then raise exception 'Too many traits.' using errcode='22023';end if;
 for l in select value from jsonb_array_elements(b->'lines') loop
  t:=dcc_private.progression_item('traits',l->>'traitId');target:=l->>'target';effect:=t->>'effect';quantity:=dcc_private.tutorial_int(l->'quantity',1,50);
  if jsonb_typeof(l->'target') is distinct from 'string' or not(t->'targets'?target) or (l->>'traitId'||'|'||target)=any(seen) then raise exception 'Unknown target or repeated trait.' using errcode='22023';end if;
  seen:=array_append(seen,l->>'traitId'||'|'||target);cost:=(t->>'cost')::integer;spent:=spent+greatest(0,cost)*quantity;refund:=refund+greatest(0,-cost)*quantity;
  notes:=notes||E'\n'||quantity||' × '||(t->>'name')||case when target<>''then ': '||target else ''end;
  if effect='stat' then stats:=jsonb_set(stats,array[target],to_jsonb((stats->>target)::integer+quantity));end if;
  if effect='statPenalty' then stats:=jsonb_set(stats,array[target],to_jsonb((stats->>target)::integer-quantity));statpen:=statpen+quantity;
   if coalesce((bases#>>array[target,'base'])::integer,0)-quantity<1 then issues:=issues||'"stat-floor"'::jsonb;end if;
  end if;
  if effect='skillPenalty' then
   skillpen:=skillpen+quantity;penalty_counts:=jsonb_set(penalty_counts,array[target],to_jsonb(coalesce((penalty_counts->>target)::integer,0)+quantity));select value into sk from jsonb_array_elements(skills) where value->>'id'=target;
   if coalesce((sk->>'rank')::integer,0)<quantity then issues:=issues||'"skill-penalty"'::jsonb;end if;
   grants:=jsonb_set(grants,array[target],to_jsonb(coalesce((grants->>target)::integer,0)-quantity));
  end if;
  if effect='groupPenalty' then
   penalties:=jsonb_set(penalties,array[target],to_jsonb(coalesce((penalties->>target)::integer,0)-quantity));
   if not exists(select 1 from jsonb_array_elements(skills)where value->>'stat'=target)then issues:=issues||'"skill-penalty"'::jsonb;end if;
   for sk in select value from jsonb_array_elements(skills)where value->>'stat'=target loop k:=sk->>'id';penalty_counts:=jsonb_set(penalty_counts,array[k],to_jsonb(coalesce((penalty_counts->>k)::integer,0)+quantity));end loop;
  end if;
  ids:='[]';
  if effect='skill' then ids:=jsonb_build_array(target);end if;
  if effect like 'skillGroup%' then ids:=dcc_private.progression_data()#>array['groups',target];end if;
  if effect='skillGroupSmall' and jsonb_array_length(ids) not between 3 and 5 then issues:=issues||'"group"'::jsonb;end if;
  if effect='skillGroupLarge' and jsonb_array_length(ids)<6 then issues:=issues||'"group"'::jsonb;end if;
  if effect='rank20Six' and jsonb_array_length(dcc_private.progression_data()#>array['groups',target])>6 then issues:=issues||'"group"'::jsonb;end if;
  for v in select value from jsonb_array_elements(ids) loop
   k:=v#>>'{}';a:=dcc_private.progression_item('abilities',k);n:=coalesce((grants->>k)::integer,0)+quantity;grants:=jsonb_set(grants,array[k],to_jsonb(n));
   if a->>'passive'='true' then passives:=passives+quantity;end if;
   if n>10 then issues:=issues||'"selection-cap"'::jsonb;end if;
  end loop;
  if effect='dr' then dr:=dr+quantity;if dr>3 then issues:=issues||'"dr"'::jsonb;end if;end if;
  if effect='move' then move:=move+5*quantity;end if;if effect='step' then step:=step+5*quantity;end if;if effect='size' then size:=2;end if;
  if effect='statCap' then caps:=jsonb_set(caps,array[target],'10');end if;
  if effect='rank20' then rank20:=rank20||jsonb_build_array(target);end if;
  if effect='rank20All' then rankgroups:=rankgroups||'"all"'::jsonb;end if;
  if effect in ('rank20Group','rank20Six') then rankgroups:=rankgroups||jsonb_build_array(target);end if;
  if effect in ('resistant','vulnerable','poisonImmune') then
   k:=case when effect='poisonImmune' then 'Poison' else target end;prior:=coalesce(defenses->k,'{"resistant":false,"vulnerable":false,"immune":false}'::jsonb);
   defenses:=jsonb_set(defenses,array[k],jsonb_set(prior,array[case when effect='poisonImmune' then 'immune' else effect end],'true'));
  end if;
  if effect in ('resistant','vulnerable','poisonImmune','rank20','rank20Group','rank20All','rank20Six','statCap','size') and quantity<>1 then issues:=issues||'"stacking"'::jsonb;end if;
  if effect='advancePenalty' and not exists(select 1 from jsonb_array_elements(skills)where value->>'id'=target and(value->>'rank')::integer>=5)then issues:=issues||'"advance-penalty"'::jsonb;end if;
 end loop;
 if b?'bespoke'then
  if jsonb_typeof(b->'bespoke')is distinct from 'array'or jsonb_array_length(b->'bespoke')>10 then raise exception 'Invalid bespoke benefits.'using errcode='22023';end if;
  for v in select value from jsonb_array_elements(b->'bespoke')loop
   if jsonb_typeof(v->'name')is distinct from 'string'or length(btrim(v->>'name'))not between 1 and 120 or jsonb_typeof(v->'description')is distinct from 'string'or length(btrim(v->>'description'))not between 1 and 1000 then raise exception 'Enter a bespoke name and ruling.'using errcode='22023';end if;
   n:=dcc_private.tutorial_int(v->'points',-5,30);spent:=spent+greatest(0,n);refund:=refund+greatest(0,-n);notes:=notes||E'\nGM-priced '||n||' BP: '||(v->>'name')||': '||(v->>'description');
  end loop;
 end if;
 for sk in select value from jsonb_array_elements(skills)loop
  n:=coalesce((penalty_counts->>(sk->>'id'))::integer,0);
  if n>(sk->>'rank')::integer then issues:=issues||'"skill-penalty"'::jsonb;end if;
 end loop;
 refund:=refund+statpen/2+skillpen/2;
 if spent>(case when b->>'kind'='race' then 25 else 30 end)+least(5,refund)then issues:=issues||'"budget"'::jsonb;end if;
 if b->>'kind'='class' and passives>5 then issues:=issues||'"passive-cap"'::jsonb;end if;
 result:=jsonb_build_object('name',b->'name','kind',b->'kind','page',158,'earth',b->'earth','earthOnly',b->>'kind'='class' and b->>'earth'='true','size',size,'stats',stats,'skills',grants,'dr',dr,'move',move,'step',step,'defenses',defenses,'requirements','[]'::jsonb,'choices','[]'::jsonb,'rank20',rank20,'rank20Groups',rankgroups,'statCaps',caps,'skillPenalties',penalties,'splitStats',null,'notes',notes);
 return jsonb_build_object('option',result,'issues',(select coalesce(jsonb_agg(distinct value),'[]') from jsonb_array_elements(issues)),'cost',jsonb_build_object('spent',spent,'refunded',refund,'usableRefund',least(5,refund)));
end $$;

create function dcc_private.progression_option(state jsonb,ident text) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
 if ident like 'custom-%' then select value->'option' into result from jsonb_array_elements(state->'definitions')where value->>'id'=ident and value->>'approved'='true';
 else select value into result from jsonb_array_elements(dcc_private.progression_data()->'options')where value->>'id'=ident;end if;
 if result is null then raise exception 'Choose a reviewed definition.' using errcode='22023';end if;return result;
end $$;
create function dcc_private.progression_requirements(o jsonb,bases jsonb,skills jsonb,evidence jsonb,race_id text) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare req jsonb;v jsonb;passed boolean;issues jsonb:='[]';i integer:=0;kind text;ids jsonb;
begin
 for req in select value from jsonb_array_elements(o->'requirements')loop
  kind:=req->>'kind';passed:=false;
  if kind='fact' then v:=evidence#>array['facts',req->>'key'];passed:=case when req->'value'='true'::jsonb then v is not null and v not in ('false'::jsonb,'""'::jsonb,'null'::jsonb)else v=req->'value'end;end if;
  if kind in ('skill','anySkill','groupSkill','physicalSkill') then
   ids:=case when kind='skill' then jsonb_build_array(req->>'id')when kind='anySkill' then req->'ids'when kind='groupSkill' then dcc_private.progression_data()#>array['groups',req->>'group']else '[]'::jsonb end;
   passed:=exists(select 1 from jsonb_array_elements(skills)where(value->>'rank')::integer>=(req->>'rank')::integer and((kind='physicalSkill' and value->>'stat' in ('strength','dexterity'))or ids?(value->>'id')));
  end if;
  if kind='popularity' then passed:=jsonb_typeof(evidence->'popularity')='number' and (evidence->>'popularity')::integer>=(req->>'minimum')::integer;end if;
  if kind='race' then passed:=req->'ids'?race_id;end if;
  if kind='identity' then passed:=evidence->>'identityLimits'='false' or evidence#>array['facts',req->>'key']='true'::jsonb;end if;
  if kind='minimum' then passed:=(bases#>>array[req->>'stat','base'])::integer>=(req->>'minimum')::integer;end if;
  if passed is distinct from true then issues:=issues||jsonb_build_array((o->>'id')||':'||i);end if;i:=i+1;
 end loop;return issues;
end $$;
create function dcc_private.progression_pair_issues(state jsonb,race jsonb,profession jsonb,bases jsonb,skills jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare issues jsonb;d jsonb;result jsonb;v jsonb;
begin
 issues:=dcc_private.progression_requirements(race,bases,skills,state->'evidence',race->>'id')||dcc_private.progression_requirements(profession,bases,skills,state->'evidence',race->>'id');
 if profession->>'earthOnly'='true' and race->>'earth'<>'true'then issues:=issues||'"earth"'::jsonb;end if;
 if ((race->>'id' like 'custom-%'and race->>'earth'='true')or profession->>'earthOnly'='true')and state->'rewardDecision'='null'::jsonb then issues:=issues||'"earth-reward"'::jsonb;end if;
 for d in select value from jsonb_array_elements(state->'definitions')where value->>'id' in (race->>'id',profession->>'id')loop
  result:=dcc_private.progression_custom(d->'build',bases,skills);
  for v in select value from jsonb_array_elements(result->'issues')loop if not(d->'waivers'?(v#>>'{}'))then issues:=issues||jsonb_build_array((d->>'id')||':'||(v#>>'{}'));end if;end loop;
 end loop;return issues;
end $$;

create function public.dcc_progression_action(p_crawler_id uuid,p_expected_version uuid,p_operation text,p_payload jsonb) returns void
language plpgsql security definer set search_path='' as $$
declare r public.dcc_crawlers%rowtype;state jsonb;before_state jsonb;baseline jsonb;skills jsonb;defenses jsonb;tf jsonb;result jsonb;d jsonb;o jsonb;v jsonb;l jsonb;a jsonb;race jsonb;profession jsonb;options jsonb;offer jsonb;issues jsonb;choices jsonb;waivers jsonb;skip jsonb;split jsonb;grants jsonb:='{}';rankids jsonb:='[]';penalties jsonb:='{}';applied jsonb:='[]';valid_skip jsonb:='[]';original jsonb;existing jsonb;flags jsonb;prior jsonb;selection jsonb;gm boolean;k text;key text;new_id text;reason text;summary text;operation text;position integer;n integer;amount integer;dr integer;cap integer;size integer;move integer;step integer;count_choices integer;seen text[]:=array[]::text[];
begin
 if auth.uid()is null then raise exception 'Sign in first.' using errcode='42501';end if;
 select * into r from public.dcc_crawlers where id=p_crawler_id for update;
 if not found or not dcc_private.is_member(r.campaign_id) then raise exception 'Crawler access denied.' using errcode='42501';end if;
 gm:=dcc_private.is_gm(r.campaign_id);
 if not gm and r.owner_user_id is distinct from auth.uid()then raise exception 'Crawler access denied.' using errcode='42501';end if;
 if r.version is distinct from p_expected_version then raise exception 'Crawler changed; refresh.' using errcode='40001';end if;
 if r.ruleset<>'tutorial-v1'or jsonb_typeof(p_payload)is distinct from 'object'or octet_length(p_payload::text)>100000 or p_payload->'confirmed'is distinct from 'true'::jsonb then raise exception 'Invalid progression action.' using errcode='22023';end if;
 if p_operation is null or p_operation not in ('draft','approve','evidence','offer','select','reward','prepare-reconciliation')then raise exception 'Unknown progression action.' using errcode='22023';end if;
 if p_operation not in ('draft','select')and not gm then raise exception 'Only the GM reviews rules and offers.' using errcode='42501';end if;
 if jsonb_typeof(p_payload->'reason')is distinct from 'string'or length(btrim(p_payload->>'reason'))not between 1 and 500 then raise exception 'Enter a review reason.' using errcode='22023';end if;
 reason:=btrim(p_payload->>'reason');state:=r.progression;before_state:=state;baseline:=r.stat_baseline;skills:=r.learned_skills;defenses:=r.base_typed_defenses;tf:=r.third_floor;dr:=r.defense_base;
 operation:='selection-review';summary:='GM reviewed progression evidence';
 if p_operation='prepare-reconciliation'then
  if r.dungeon_floor<3 or tf->>'reviewed'='true'or tf->'selected'<>'null'::jsonb or state->'selection'<>'null'::jsonb or r.advancement->>'reconciled'<>'true'then raise exception 'Partial review requires an unreviewed, unselected Floor 3+ crawler.'using errcode='22023';end if;
  state:=jsonb_set(state,'{partialReview}','true');summary:='GM prepared partial benefit reconciliation; existing grants and Human Favor preserved';
 elsif p_operation='draft'then
  if jsonb_array_length(state->'definitions')>=30 then raise exception 'Custom draft limit reached.' using errcode='22023';end if;
  result:=dcc_private.progression_custom(p_payload->'build',baseline,skills);new_id:='custom-'||gen_random_uuid();
  d:=jsonb_build_object('id',new_id,'build',p_payload->'build','option',(result->'option')||jsonb_build_object('id',new_id),'approved',false,'waivers','[]'::jsonb,'ruling','','createdBy',auth.uid());
  state:=jsonb_set(state,'{definitions}',(state->'definitions')||jsonb_build_array(d));summary:='Saved custom Race/Class draft';
 elsif p_operation='approve'then
  waivers:=p_payload->'waivers';if jsonb_typeof(waivers)is distinct from 'array'then raise exception 'List explicit waivers.' using errcode='22023';end if;
  select value,ordinality::integer-1 into d,position from jsonb_array_elements(state->'definitions')with ordinality where value->>'id'=p_payload->>'id';
  if d is null then raise exception 'Choose a saved draft.' using errcode='22023';end if;
  result:=dcc_private.progression_custom(d->'build',baseline,skills);
  if not(result->'issues'<@waivers)or not(waivers<@(result->'issues'))then raise exception 'Review each failed rule explicitly.' using errcode='22023';end if;
  d:=d||jsonb_build_object('approved',true,'ruling',reason,'waivers',waivers,'reviewedBy',auth.uid(),'option',jsonb_set(d->'option','{notes}',to_jsonb((result#>>'{option,notes}')||E'\nGM ruling: '||reason)));state:=jsonb_set(state,array['definitions',position::text],d);summary:='GM approved custom definition and recorded rulings';
 elsif p_operation='evidence'then
  d:=p_payload->'evidence';
  if jsonb_typeof(d)is distinct from 'object'or jsonb_typeof(d->'facts')is distinct from 'object'or jsonb_typeof(d->'identityLimits')is distinct from 'boolean'then raise exception 'Invalid verified facts.' using errcode='22023';end if;
  if d->'popularity'is distinct from 'null'::jsonb then perform dcc_private.tutorial_int(d->'popularity',0,100000);end if;
  if(select count(*)from jsonb_object_keys(d->'facts'))>100 then raise exception 'Too many facts.' using errcode='22023';end if;
  for k,v in select * from jsonb_each(d->'facts')loop
   if k!~'^[a-zA-Z0-9:-]{1,80}$'or jsonb_typeof(v)not in ('string','boolean','number')or(jsonb_typeof(v)='string'and length(v#>>'{}')>120)then raise exception 'Invalid fact.' using errcode='22023';end if;
   if jsonb_typeof(v)='number'then perform dcc_private.tutorial_int(v,1,8);end if;
  end loop;
  if jsonb_typeof(d#>'{facts,originalSpecies}')='string'then d:=jsonb_set(d,'{facts,originalSpecies}',to_jsonb(lower(btrim(d#>>'{facts,originalSpecies}'))));end if;
  state:=jsonb_set(state,'{evidence}',jsonb_build_object('facts',d->'facts','popularity',d->'popularity','identityLimits',d->'identityLimits'));
 elsif p_operation='reward'then
  if state->'rewardDecision'<>'null'::jsonb or p_payload->>'decision'is null or p_payload->>'decision'not in ('issue-once','already-received','declined')then raise exception 'Earth reward decision is already recorded or invalid.' using errcode='22023';end if;
  state:=jsonb_set(state,'{rewardDecision}',p_payload->'decision');summary:='GM recorded the single Earth incentive decision; no automatic box or Skill ranks issued';
 elsif p_operation='offer'then
  if (tf->>'reviewed'<>'true'and state->>'partialReview'is distinct from'true')or tf->'selected'<>'null'::jsonb or state->'selection'<>'null'::jsonb or jsonb_typeof(p_payload->'offers')is distinct from 'array'then raise exception 'Complete benefit review before offering.' using errcode='22023';end if;
  if jsonb_array_length(p_payload->'offers')>3 or(jsonb_array_length(p_payload->'offers')>0 and r.dungeon_floor<3)then raise exception 'Offer up to three on Floor 3+.' using errcode='22023';end if;
  choices:='[]';
  for o in select value from jsonb_array_elements(p_payload->'offers')loop
   race:=dcc_private.progression_option(state,o->>'raceId');profession:=dcc_private.progression_option(state,o->>'classId');
   if race->>'kind'<>'race'or profession->>'kind'<>'class'then raise exception 'Choose Race then Class.' using errcode='22023';end if;
   key:=(race->>'id')||'|'||(profession->>'id');if key=any(seen)then raise exception 'Choose distinct offers.' using errcode='22023';end if;seen:=array_append(seen,key);
   issues:=dcc_private.progression_pair_issues(state,race,profession,baseline,skills);waivers:=o->'waivers';
   if jsonb_typeof(waivers)is distinct from 'array'or waivers?'earth-reward'or not(issues<@waivers)or not(waivers<@(issues||'["selection-rank-cap"]'::jsonb))then raise exception 'Verify or explicitly waive each constraint; record Earth rewards separately.' using errcode='22023';end if;
   choices:=choices||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'raceId',race->'id','classId',profession->'id','waivers',waivers,'reason',reason));
  end loop;
  state:=jsonb_set(state,'{offers}',choices);summary:='GM curated Race/Class offers with explicit rulings';operation:='selection-offer';
 else
  if state->>'partialReview'='true'and tf->>'reviewed'<>'true'and not gm then raise exception 'Only the GM completes partial reconciliation.'using errcode='42501';end if;
  if r.dungeon_floor<3 or r.advancement->>'reconciled'<>'true'or(tf->>'reviewed'<>'true'and state->>'partialReview'is distinct from'true')or tf->'selected'<>'null'::jsonb or state->'selection'<>'null'::jsonb then raise exception 'Selection is unavailable or already applied.' using errcode='22023';end if;
  if p_payload?'allocation'then
   perform public.dcc_advancement_action(r.id,r.version,'allocate',jsonb_build_object('allocation',p_payload->'allocation','reason',reason));
   select * into r from public.dcc_crawlers where id=p_crawler_id;baseline:=r.stat_baseline;
  end if;
  select value into offer from jsonb_array_elements(state->'offers')where value->>'id'=p_payload->>'offerId';
  if offer is null then raise exception 'Choose a current GM offer.' using errcode='22023';end if;
  race:=dcc_private.progression_option(state,offer->>'raceId');profession:=dcc_private.progression_option(state,offer->>'classId');
  issues:=dcc_private.progression_pair_issues(state,race,profession,baseline,skills);if not(issues<@(offer->'waivers'))then raise exception 'Eligibility changed; ask the GM to review.' using errcode='22023';end if;
  choices:=p_payload->'choices';skip:=p_payload->'skip';split:=p_payload->'split';
  if jsonb_typeof(choices)is distinct from 'object'or jsonb_typeof(skip)is distinct from 'array'or jsonb_typeof(split)is distinct from 'object'then raise exception 'Invalid benefit choices.' using errcode='22023';end if;
  if jsonb_array_length(skip)>0 and not gm then raise exception 'Only GM reconciles individual benefits.' using errcode='42501';end if;
  options:=jsonb_build_array(race,profession);
  if race->>'id'='primal'then original:=dcc_private.progression_item('options',state#>>'{evidence,facts,originalRace}');if original->>'kind'<>'race'or original->>'id'='primal'then raise exception 'Verify original Race.' using errcode='22023';end if;options:=jsonb_build_array(original)||options;end if;
  count_choices:=0;
  for o in select value from jsonb_array_elements(options)loop
   valid_skip:=valid_skip||jsonb_build_array((o->>'id')||':penalties',(o->>'id')||':split');
   if not(skip?((o->>'id')||':penalties'))and exists(select 1 from jsonb_object_keys(o->'skillPenalties'))then applied:=applied||jsonb_build_array((o->>'id')||':penalties');end if;
   foreach k in array array['strength','intelligence','constitution','dexterity','charisma']loop
    key:=(o->>'id')||':stat:'||k;valid_skip:=valid_skip||jsonb_build_array(key);
    if not(skip?key)then baseline:=jsonb_set(baseline,array[k,'base'],to_jsonb((baseline#>>array[k,'base'])::integer+(o#>>array['stats',k])::integer));if(o#>>array['stats',k])::integer<>0 then applied:=applied||jsonb_build_array(key);end if;end if;
    if not(skip?((o->>'id')||':penalties'))then penalties:=jsonb_set(penalties,array[k],to_jsonb(coalesce((penalties->>k)::integer,0)+coalesce((o#>>array['skillPenalties',k])::integer,0)));end if;
   end loop;
   for k,v in select * from jsonb_each(o->'skills')loop
    key:=(o->>'id')||':skill:'||k;valid_skip:=valid_skip||jsonb_build_array(key);if not(skip?key)then grants:=jsonb_set(grants,array[k],to_jsonb(coalesce((grants->>k)::integer,0)+(v#>>'{}')::integer));applied:=applied||jsonb_build_array(key);end if;
   end loop;
   key:=(o->>'id')||':dr';valid_skip:=valid_skip||jsonb_build_array(key);if not(skip?key)then dr:=dr+(o->>'dr')::integer;if(o->>'dr')::integer<>0 then applied:=applied||jsonb_build_array(key);end if;end if;
   rankids:=rankids||(o->'rank20');for v in select value from jsonb_array_elements(o->'rank20Groups')loop rankids:=rankids||(dcc_private.progression_data()#>array['groups',v#>>'{}']);end loop;
   for d in select value from jsonb_array_elements(o->'choices')loop
    count_choices:=count_choices+1;key:=(o->>'id')||'.'||(d->>'id');l:=choices->key;
    if jsonb_typeof(l)is distinct from 'array'or jsonb_array_length(l)<>(d->>'count')::integer then raise exception 'Complete benefit choices.' using errcode='22023';end if;
    seen:=array[]::text[];
    for v in select value from jsonb_array_elements(l)loop
     k:=v#>>'{}';if jsonb_typeof(v)<>'string'or not(d->'ids'?k)or k=any(seen)then raise exception 'Invalid or repeated benefit choice.' using errcode='22023';end if;seen:=array_append(seen,k);
     if d->>'cap20'='true'then rankids:=rankids||jsonb_build_array(k);end if;
     key:=(o->>'id')||':choice:'||(d->>'id')||':'||k;valid_skip:=valid_skip||jsonb_build_array(key);if not(skip?key)and(d->>'bonus')::integer<>0 then grants:=jsonb_set(grants,array[k],to_jsonb(coalesce((grants->>k)::integer,0)+(d->>'bonus')::integer));applied:=applied||jsonb_build_array(key);end if;
    end loop;
   end loop;
   if o->'splitStats'<>'null'::jsonb then
    n:=0;foreach k in array array['strength','intelligence','constitution','dexterity','charisma']loop amount:=dcc_private.tutorial_int(coalesce(split#>array[o->>'id',k],'0'::jsonb),0,(o#>>'{splitStats,total}')::integer);if amount>0 and not(o#>'{splitStats,keys}'?k)then raise exception 'Invalid split Stat.' using errcode='22023';end if;n:=n+amount;if not(skip?((o->>'id')||':split'))then baseline:=jsonb_set(baseline,array[k,'base'],to_jsonb((baseline#>>array[k,'base'])::integer+amount));end if;end loop;
    if n<>(o#>>'{splitStats,total}')::integer then raise exception 'Spend exactly the split bonus.' using errcode='22023';end if;
    if not(skip?((o->>'id')||':split'))then applied:=applied||jsonb_build_array((o->>'id')||':split');end if;
   end if;
   for k,flags in select * from jsonb_each(o->'defenses')loop prior:=defenses->k;defenses:=jsonb_set(defenses,array[k],jsonb_build_object('resistant',coalesce((prior->>'resistant')::boolean,false)or(flags->>'resistant')::boolean,'vulnerable',coalesce((prior->>'vulnerable')::boolean,false)or(flags->>'vulnerable')::boolean,'immune',coalesce((prior->>'immune')::boolean,false)or(flags->>'immune')::boolean));end loop;
  end loop;
  if(select count(*)from jsonb_object_keys(choices))<>count_choices or not(skip<@valid_skip)or(select count(distinct value)from jsonb_array_elements(skip))<>jsonb_array_length(skip)then raise exception 'Unexpected benefit or reconciliation choices.' using errcode='22023';end if;
  for k,v in select * from jsonb_each(grants)loop
   a:=dcc_private.progression_item('abilities',k);amount:=(v#>>'{}')::integer;
   if k='heal'then raise exception 'Tutorial Heal is protected.' using errcode='22023';end if;
   existing:=null;position:=null;select value,ordinality::integer-1 into existing,position from jsonb_array_elements(skills)with ordinality where value->>'id'=k or lower(value->>'name')=lower(a->>'name')limit 1;
   if existing is not null and(existing->>'kind'<>a->>'kind'or lower(existing->>'name')<>lower(a->>'name'))then raise exception 'Conflicting ability; review required.' using errcode='22023';end if;
   cap:=case when rankids?k or(offer->'waivers')?'selection-rank-cap'then 20 else coalesce((existing->>'maxRank')::integer,(a->>'maxRank')::integer)end;
   n:=case when amount<0 then coalesce((existing->>'rank')::integer,0)+amount else greatest(coalesce((existing->>'rank')::integer,0),least(case when(offer->'waivers')?'selection-rank-cap'then 20 else 10 end,cap,coalesce((existing->>'rank')::integer,0)+amount))end;
   if n<0 then raise exception 'Cannot remove unlearned ranks.' using errcode='22023';end if;
   if n=0 then if position is not null then skills:=skills-position;end if;continue;end if;
   d:=coalesce(existing,a||jsonb_build_object('origin','gm','marked',false))||jsonb_build_object('rank',n,'maxRank',cap);
   if n>=15 then d:=jsonb_set(d,'{marked}','false');end if;
   if position is null then skills:=skills||jsonb_build_array(d);else skills:=jsonb_set(skills,array[position::text],d);end if;
  end loop;
  result:='[]';for d in select value from jsonb_array_elements(skills)loop
   n:=(d->>'rank')::integer;
   for o in select value from jsonb_array_elements(options)loop if n>0 and not(skip?((o->>'id')||':penalties'))then n:=greatest(case when o->>'id'='mage'then 1 else 0 end,n+coalesce((o#>>array['skillPenalties',d->>'stat'])::integer,0));end if;end loop;
   if n=0 then continue;end if;
   d:=jsonb_set(d,'{rank}',to_jsonb(n));if rankids?(d->>'id')then d:=jsonb_set(d,'{maxRank}','20');end if;result:=result||jsonb_build_array(d);
  end loop;skills:=result;
  foreach k in array array['strength','intelligence','constitution','dexterity','charisma']loop perform dcc_private.tutorial_int(baseline#>array[k,'base'],1,10000);end loop;
  for o in select value from jsonb_array_elements(options)loop for k,v in select * from jsonb_each(o->'statCaps')loop baseline:=jsonb_set(baseline,array[k,'base'],to_jsonb(least((baseline#>>array[k,'base'])::integer,(v#>>'{}')::integer)));end loop;end loop;
  move:=coalesce((race->>'move')::integer,20)+case when race->>'id'='tigran'then 10 else 0 end;step:=coalesce((race->>'step')::integer,10);size:=case when race->>'id'in('primal','doppelganger')then coalesce((state#>>'{evidence,facts,originalSize}')::integer,4)else(race->>'size')::integer end;
  selection:=jsonb_build_object('race',race,'profession',profession,'inheritedRace',original,'choices',choices,'applied',applied,'skipped',skip,'waivers',offer->'waivers','rulesVersion',dcc_private.progression_data()->'version','actor',auth.uid(),'reason',reason);
  state:=jsonb_set(jsonb_set(state,'{selection}',selection),'{offers}','[]');
  -- 018 remains the identity/Favor projection. Custom or overridden incompatible
  -- identities use its existing reviewed-manual representation; full definitions
  -- and the actual applied mode/provenance are retained above.
  tf:=jsonb_build_object('reviewed',true,'offers','[]'::jsonb,'selected',jsonb_build_object('raceId',case when race->>'id'like'custom-%'then'manual'else race->>'id'end,'classId',case when profession->>'id'like'custom-%'or(profession->>'earthOnly'='true'and race->>'earth'<>'true')then'manual'else profession->>'id'end,'raceName',race->'name','className',profession->'name','size',size,'move',move,'step',step,'mode',case when race->>'id'like'custom-%'or profession->>'id'like'custom-%'or(profession->>'earthOnly'='true'and race->>'earth'<>'true')then'reconciled'else'applied'end,'notes',reason));
  summary:='Selected Race/Class; supported benefits applied once with reconciliation provenance';operation:='selection-apply';
 end if;
 update public.dcc_crawlers set progression=state,third_floor=tf,stat_baseline=baseline,learned_skills=skills,defense_base=dr,base_typed_defenses=defenses,version=gen_random_uuid()where id=r.id;
 insert into public.dcc_advancement_history(campaign_id,crawler_id,actor_user_id,operation,summary,reason,details)values(r.campaign_id,r.id,auth.uid(),operation,summary,reason,jsonb_build_object('before',before_state,'after',state,'previousStats',r.stat_baseline,'previousSkills',r.learned_skills,'previousDR',r.defense_base));
end $$;

-- Keep already-saved 018 offers valid. New definitions must use the expanded
-- checked workflow so its prerequisite/evidence checks cannot be bypassed.
alter function public.dcc_third_floor_action(uuid,uuid,text,jsonb)set schema dcc_private;
alter function dcc_private.dcc_third_floor_action(uuid,uuid,text,jsonb)rename to third_floor_018;
create function public.dcc_third_floor_action(p_crawler_id uuid,p_expected_version uuid,p_operation text,p_payload jsonb default '{}')returns void language plpgsql security definer set search_path='' as $$
declare key text;
begin
 if p_operation='partial-review'then perform public.dcc_progression_action(p_crawler_id,p_expected_version,'prepare-reconciliation',p_payload);return;end if;
 if p_operation='offer'then for key in select value#>>'{}'from jsonb_array_elements(p_payload->'offers')loop
  if split_part(key,'|',1)not in('human','amazonian','crocodilian','igneous','pterolykos')or split_part(key,'|',2)not in('fighter','pit-fighter','blizzardmancer','monster-truck-driver')then raise exception 'Use the expanded workflow.'using errcode='22023';end if;
 end loop;end if;
 perform dcc_private.third_floor_018(p_crawler_id,p_expected_version,p_operation,p_payload);
end $$;
create function dcc_private.progression_floor_change()returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.dungeon_floor is distinct from old.dungeon_floor and jsonb_array_length(new.progression->'offers')>0 then
  insert into public.dcc_advancement_history(campaign_id,crawler_id,actor_user_id,operation,summary,reason,details)values(new.campaign_id,new.id,auth.uid(),'selection-offer','Race/Class offers closed','Floor changed.',jsonb_build_object('fromFloor',old.dungeon_floor,'toFloor',new.dungeon_floor));
  new.progression:=jsonb_set(new.progression,'{offers}','[]');
 end if;return new;
end $$;
create trigger dcc_ab_progression_floor before update on public.dcc_crawlers for each row execute function dcc_private.progression_floor_change();
-- Carry reviewed caps in the baseline so all existing loadout calculations can
-- apply them to equipped totals too. Reassert from the immutable selection on
-- every write; clients cannot remove a cap through a baseline correction.
create function dcc_private.progression_caps()returns trigger language plpgsql security definer set search_path=''as $$
declare o jsonb;k text;v jsonb;caps jsonb:='{}';n integer;
begin
 if new.ruleset<>'tutorial-v1'or new.progression->'selection'='null'::jsonb then return new;end if;
 for o in select value from jsonb_array_elements(jsonb_build_array(new.progression#>'{selection,race}',new.progression#>'{selection,profession}',new.progression#>'{selection,inheritedRace}'))loop
  for k,v in select * from jsonb_each(o->'statCaps')loop caps:=jsonb_set(caps,array[k],to_jsonb(least(coalesce((caps->>k)::integer,10000),(v#>>'{}')::integer)));end loop;
 end loop;
 for k,v in select * from jsonb_each(caps)loop n:=(v#>>'{}')::integer;if(new.stat_baseline#>>array[k,'base'])::integer>n then raise exception 'Unenhanced Stat exceeds the selected cap; do not spend points above it.'using errcode='22023';end if;new.stat_baseline:=jsonb_set(new.stat_baseline,array[k,'cap'],v);end loop;return new;
end $$;
create trigger dcc_y_progression_caps before insert or update on public.dcc_crawlers for each row execute function dcc_private.progression_caps();
create or replace function dcc_private.project_third_floor()returns trigger language plpgsql security definer set search_path=''as $$
declare state jsonb;
begin
 if new.ruleset<>'tutorial-v1'then return new;end if;
 state:=dcc_private.normalize_third_floor(new.third_floor);
 if tg_op='UPDATE'and new.dungeon_floor is distinct from old.dungeon_floor and jsonb_array_length(state->'offers')>0 then
  state:=jsonb_set(state,'{offers}','[]');
  insert into public.dcc_advancement_history(campaign_id,crawler_id,actor_user_id,operation,summary,reason,details)values(new.campaign_id,new.id,auth.uid(),'selection-offer','Race/Class offers closed','Floor changed.',jsonb_build_object('fromFloor',old.dungeon_floor,'toFloor',new.dungeon_floor));
 end if;
 if state->>'reviewed'='true'then new.advancement:=jsonb_set(new.advancement,'{humanFavor}',to_jsonb(coalesce(state#>>'{selected,raceId}'='human',false)or coalesce(new.progression#>>'{selection,inheritedRace,id}'='human',false)));end if;
 new.third_floor:=state;return new;
end $$;
alter function dcc_private.loadout_totals(jsonb,jsonb,integer)rename to loadout_before_progression;
alter function dcc_private.sheet_baseline(jsonb,jsonb)rename to sheet_before_progression;
create function dcc_private.sheet_baseline(baseline jsonb,effects jsonb)returns jsonb language plpgsql security definer set search_path=''as $$
declare result jsonb;k text;cap integer;
begin
 result:=dcc_private.sheet_before_progression(baseline,effects);
 foreach k in array array['strength','intelligence','constitution','dexterity','charisma']loop
  if baseline->k?'cap'then cap:=dcc_private.tutorial_int(baseline#>array[k,'cap'],1,10000);result:=jsonb_set(result,array[k,'cap'],to_jsonb(cap));end if;
 end loop;return result;
end $$;
create function dcc_private.loadout_totals(p_base jsonb,p_items jsonb,p_dr integer)returns jsonb language plpgsql security definer set search_path=''as $$
declare result jsonb;k text;cap integer;
begin
 result:=dcc_private.loadout_before_progression(p_base,p_items,p_dr);
 foreach k in array array['strength','intelligence','constitution','dexterity','charisma']loop
  if p_base->k?'cap'then cap:=dcc_private.tutorial_int(p_base#>array[k,'cap'],1,10000);result:=jsonb_set(result,array['stats',k,'enhanced'],to_jsonb(least(cap,(result#>>array['stats',k,'enhanced'])::integer)));end if;
 end loop;
 result:=jsonb_set(result,'{evade}',to_jsonb(dcc_private.tutorial_modifier((result#>>'{stats,dexterity,enhanced}')::integer)+(result#>>'{gear,evade}')::integer));return result;
end $$;
revoke all on function dcc_private.progression_caps(),dcc_private.sheet_before_progression(jsonb,jsonb),dcc_private.sheet_baseline(jsonb,jsonb),dcc_private.loadout_before_progression(jsonb,jsonb,integer),dcc_private.loadout_totals(jsonb,jsonb,integer)from public,anon,authenticated;
revoke all on function dcc_private.progression_data(),dcc_private.progression_item(text,text),dcc_private.progression_custom(jsonb,jsonb,jsonb),dcc_private.progression_option(jsonb,text),dcc_private.progression_requirements(jsonb,jsonb,jsonb,jsonb,text),dcc_private.progression_pair_issues(jsonb,jsonb,jsonb,jsonb,jsonb),dcc_private.third_floor_018(uuid,uuid,text,jsonb),dcc_private.progression_floor_change()from public,anon,authenticated;
revoke all on function public.dcc_progression_action(uuid,uuid,text,jsonb),public.dcc_third_floor_action(uuid,uuid,text,jsonb)from public,anon,authenticated;
grant execute on function public.dcc_progression_action(uuid,uuid,text,jsonb),public.dcc_third_floor_action(uuid,uuid,text,jsonb)to authenticated;
notify pgrst,'reload schema';
commit;
